	inline constexpr usize EventTypeNameCount = sizeof(EventTypeNames) / sizeof(EventTypeNames[0]);

	/// The declared name of a type hash.
	///
	/// AN UNKNOWN HASH IS NOT AN ERROR AND NOT AN EMPTY STRING. A log written
	/// by a build with a type this one does not have is a thing that will
	/// happen, and the honest answer is the hash itself - `?0123456789abcdef`,
	/// which a person can grep for. An empty name would make a census print a
	/// blank row and look like a bug in the census.
	///
	/// The buffer is the CALLER's, and per-thread reuse is the caller's problem
	/// to have rather than a static this header hides. 18 bytes: '?', 16 hex
	/// digits, NUL.
	inline const char* NameOfEventType(Hash64 TypeHash, char (&Unknown)[18]) noexcept
	{
		usize Low = 0;
		usize High = EventTypeNameCount;
		while (Low < High)
		{
			const usize Mid = Low + (High - Low) / 2;
			if (EventTypeNames[Mid].TypeHash == TypeHash)
			{
				return EventTypeNames[Mid].Name;
			}
			if (EventTypeNames[Mid].TypeHash < TypeHash)
			{
				Low = Mid + 1;
			}
			else
			{
				High = Mid;
			}
		}
		std::snprintf(Unknown, sizeof(Unknown), "?%016llx", static_cast<unsigned long long>(TypeHash));
		return Unknown;
	}
